// Anti-pattern: the UI owns AND mutates its own state
@Composable
fun CounterAntiPattern() {
    var count by remember { mutableStateOf(0) }
    Button(onClick = { count++ }) { Text("$count") }
}

// UDF: state is owned above the UI and flows down; events flow up
@Composable
fun Counter(count: Int, onIncrement: () -> Unit) {
    Button(onClick = onIncrement) { Text("$count") }
}

@Composable
fun CounterScreen(viewModel: CounterViewModel) {
    val count by viewModel.count.collectAsStateWithLifecycle()
    Counter(count = count, onIncrement = viewModel::increment)
}

// 1. Local state — dies with the composition
@Composable
fun ExpandableSection() {
    var expanded by remember { mutableStateOf(false) }
    ExpandButton(expanded = expanded, onToggle = { expanded = !expanded })
}

// 2. Plain state holder — hoisted, testable, still tied to the composition
@Stable
class SearchFieldState(initial: String = "") {
    var query by mutableStateOf(initial)
    fun onQueryChanged(next: String) { query = next }
}

// 3. ViewModel — survives rotation AND process death, injects repositories
@HiltViewModel
class ProfileViewModel @Inject constructor(
    private val repo: ProfileRepository,
) : ViewModel() {
    private val _state = MutableStateFlow(ProfileUiState())
    val state: StateFlow<ProfileUiState> = _state.asStateFlow()

    init {
        viewModelScope.launch {
            repo.observeProfile().collect { profile ->
                _state.value = ProfileUiState(profile)
            }
        }
    }
}

sealed interface ScreenState {
    data object Loading : ScreenState
    data class Error(val message: String, val retryable: Boolean = true) : ScreenState
    data object Empty : ScreenState
    data class Content(val items: ImmutableList<Item>) : ScreenState
}

data class HomeUiState(
    val screen: ScreenState = ScreenState.Loading,
    val isRefreshing: Boolean = false,   // partial state coexists with Content
)

@Composable
fun HomeScreen(viewModel: HomeViewModel) {
    val state by viewModel.state.collectAsStateWithLifecycle()

    when (val screen = state.screen) {
        ScreenState.Loading -> LoadingSpinner()
        is ScreenState.Error -> ErrorPane(
            message = screen.message,
            onRetry = viewModel::load,
        )
        ScreenState.Empty -> EmptyHint(onAction = viewModel::load)
        is ScreenState.Content -> Column {
            if (state.isRefreshing) RefreshIndicator()
            ItemList(items = screen.items)
        }
    }
}

// Before — flag soup: every combination is representable, most are meaningless
data class MessyUiState(
    val showDialog: Boolean = false,
    val dialogKind: Int = 0,
    val isListLoading: Boolean = false,
    val isHeaderLoading: Boolean = false,
    val listError: String? = null,
    val headerError: String? = null,
    val canSubmit: Boolean = false,
)

// After — derived values, per-region state, one dialog slot
sealed interface HeaderState {
    data object Loading : HeaderState
    data class Loaded(val title: String) : HeaderState
}

class ListState {
    var items by mutableStateOf<List<Item>>(emptyList())
    var isRefreshing by mutableStateOf(false)
    var error by mutableStateOf<String?>(null)
}

data class CleanUiState(
    val header: HeaderState = HeaderState.Loading,
    val list: ListState = ListState(),
    val dialog: DialogConfig? = null,   // null == hidden
)

// Derived, never stored in state
@Composable
fun SubmitButton(text: String, selected: Item?, isRefreshing: Boolean) {
    val canSubmit by remember(text, selected, isRefreshing) {
        derivedStateOf { text.isNotBlank() && selected != null && !isRefreshing }
    }
    Button(onClick = {}, enabled = canSubmit) { Text("Submit") }
}

// MVP: the Presenter drives an imperative View contract
interface ItemListView {
    fun showLoading()
    fun showError(message: String)
    fun showItems(items: List<Item>)
    fun showEmpty()
}

class ItemListPresenter(
    private val view: ItemListView,
    private val repo: ItemRepository,
) {
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main)

    fun load() {
        view.showLoading()
        scope.launch {
            runCatching { repo.load() }
                .onSuccess { items -> if (items.isEmpty()) view.showEmpty() else view.showItems(items) }
                .onFailure { view.showError(it.message ?: "error") }
        }
    }
}

// The Compose replacement: the View contract becomes DATA
sealed interface ScreenState {
    data object Loading : ScreenState
    data class Error(val message: String) : ScreenState
    data object Empty : ScreenState
    data class Content(val items: List<Item>) : ScreenState
}

@Composable
fun ItemListHost(state: ScreenState) = when (state) {
    ScreenState.Loading -> LoadingSpinner()
    is ScreenState.Error -> ErrorPane(state.message)
    ScreenState.Empty -> EmptyHint()
    is ScreenState.Content -> ItemList(state.items)
}

class SingleLiveEvent<T> : MutableLiveData<T>() {

    override fun observe(owner: LifecycleOwner, observer: Observer<in T>) {
        super.observe(owner) { value ->
            if (hasActiveObservers()) {
                value?.let { observer.onChanged(it) }
                value = null   // consumed by ONE observer, gone for everyone else
            }
        }
    }

    // 1. A second observer (logger, second screen, test) silently never sees events.
    // 2. Rotation between setValue and consumption: the recreated screen
    //    re-subscribes to the already-nulled value — snackbar/navigation vanish.
    // 3. postValue from a background thread can land after the reset, double-delivering.
}

sealed interface NavKey
data object Home : NavKey
data class Detail(val id: String) : NavKey

@Composable
fun App() {
    val navBackStack = rememberNavBackStack(Home)   // restored across process death

    val currentKey: NavKey by derivedStateOf { navBackStack.last() }

    fun pop() {
        if (navBackStack.size > 1) navBackStack.removeAt(navBackStack.lastIndex)
    }

    when (currentKey) {
        is Home -> HomeScreen(
            onOpenItem = { id -> navBackStack.add(Detail(id)) },  // push == list add
            onBack = ::pop,
        )
        is Detail -> DetailScreen(
            id = (currentKey as Detail).id,
            onBack = ::pop,
        )
    }
}

// RIGHT: a coarse, UI-agnostic, source-of-truth boundary
class ItemsRepository(
    private val local: ItemDao,
    private val remote: ItemApi,
) {
    // The database is the source of truth the UI observes
    fun observeItems(): Flow<List<Item>> =
        local.observeAll().map { rows -> rows.map { it.toDomain() } }

    // Refresh is a data-layer policy: fetch into Room, let the Flow re-emit
    suspend fun refresh() {
        val fresh = remote.fetchItems()
        local.upsertAll(fresh.map { it.toEntity() })
    }
}

// WRONG: UI concerns smuggled into the data boundary
class LeakyRepository(private val navController: NavController) {
    var lastLoading: Boolean = false            // UI state in a repository

    suspend fun loadAndNavigate(id: String) {   // navigation in a repository
        lastLoading = false
        navController.navigate("detail/$id")    // NavController dependency
    }
}

// The generic it replaced (conceptually):
// NetworkBoundResource<T> ran loadFromDb() -> shouldFetch() -> createCall()
// -> saveCallResult() and emitted Resource<T>(status, data, message) with a
// fixed cache-first-then-network script, no paging, and no cancellation story.

// What replaced it: Room is the single source of truth, refresh writes into it
class FeedRepository(
    private val dao: FeedDao,
    private val api: FeedApi,
) {
    // The UI observes ONLY this — the database
    fun observeFeed(): Flow<List<FeedItem>> =
        dao.observeAll().map { rows -> rows.map { it.toDomain() } }

    // Refresh is a plain data-layer function: fetch, upsert, Flow re-emits.
    // Readable, testable, and cancellable like any other suspend call.
    suspend fun refresh() {
        val fresh = api.fetch()
        dao.upsertAll(fresh.map { it.toEntity() })
    }
}

class ProfileViewModel(
    private val savedStateHandle: SavedStateHandle,
    private val repo: ProfileRepository,
) : ViewModel() {

    // Constructor-time guarantee: restored BEFORE init runs
    private val profileId: String =
        checkNotNull(savedStateHandle.get<String>("profileId"))

    private val _state = MutableStateFlow(ProfileUiState())
    val state: StateFlow<ProfileUiState> = _state.asStateFlow()

    init {
        viewModelScope.launch {
            // Re-hydrate from the source of truth, keyed by the saved id
            repo.observeProfile(profileId).collect { profile ->
                _state.value = ProfileUiState(profile)
            }
        }
    }

    // Small values live in the handle; large payloads stay in Room/DataStore
    fun saveCursor(offset: Int) {
        savedStateHandle["cursor"] = offset
    }
}
